	@ParameterizedTest
	@ValueSource(ints = { 0, 2 })
	void parallelOpenerRevalidatesReadViewAfterGrowthBarrier(int siblings, @TempDir Path directory) throws Exception {
		Path transcript = directory.resolve("growth-barrier-child.txt");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-Xmx512m", "-cp", System.getProperty("java.class.path"),
				LmdbNativeParallelAdmissionTest.class.getName(), directory.resolve("store").toString(),
				Integer.toString(siblings)).redirectErrorStream(true).redirectOutput(transcript.toFile()).start();
		boolean finished;
		try {
			finished = child.waitFor(15, TimeUnit.SECONDS);
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
				assertTrue(child.waitFor(5, TimeUnit.SECONDS), "the bounded native regression must reap its child");
			}
		}
		String output = Files.readString(transcript);
		assertTrue(finished, "the growth/barrier interleaving must complete: " + output);
		assertEquals(0, child.exitValue(), output);
		assertTrue(output.contains("GROWTH_BARRIER_COMPLETE"), output);
	}

